SELECT COALESCE(SUM(status = 'SUBMITTED'), 0) submitted, COALESCE(SUM(status = 'PROCESSING'), 0) processing, COALESCE(SUM(status = 'WAITING_CUSTOMER'), 0) waiting_customer, COALESCE(SUM(status = 'RESOLVED'), 0) resolved, COALESCE(SUM( status = 'SUBMITTED' AND acceptance_due_at < UTC_TIMESTAMP(6) ), 0) overdue, COALESCE(SUM( service_item_id IS NULL AND status IN ('SUBMITTED', 'PROCESSING', 'WAITING_CUSTOMER') ), 0) triage, COALESCE(SUM(closure_reason = 'CUSTOMER_CONFIRMED'), 0) customer_confirmed, COALESCE(SUM(closure_reason = 'CONFIRMATION_TIMEOUT'), 0) confirmation_timeout FROM sd_ticket WHERE
requester_id = #{actor.ownerId} AND customer_id = #{actor.organizationId}
customer_id IN
#{id}
1 = 0
